def bline(u,v):
    a,b=v[0]-u[0],v[1]-u[1]
    cells=[(u[0],u[1])]
    if a==0 and b==0: return cells
    sgnr=0 if a==0 else (1 if a>0 else -1)
    sgnc=0 if b==0 else (1 if b>0 else -1)
    if abs(a)>abs(b):
        k=max(abs(a))
        for t in range(k+1):
            cells.append((u[0]+sgnr*t, round(u[1]+b/a*t)))
    else:
        k=max(abs(b))
        for t in range(k+1):
            cells.append((round(u[0]+a/b*t), u[1]+sgnc*t))
    # filter to grid
    res=[]
    for r,c in cells:
        if 0<=r<H and 0<=c<W: res.append((r,c))
    return res
