G=load(); print(sorted(G))
D=os.path.normpath(os.environ['RLM_SESSION_DIR'])
GG={}
for q in glob.glob(D+'/../../sessions/*.jsonl'):
    t2=open(q).read().replace('\\n','\n')
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t2):
        k,h,w=m[1],int(m[2]),int(m[3])
